type Mode='answer'|'bluff'|'trap'|'who'|'draw'|'monster'|'story'|'tanks'|'whale'|'alibi'|'roulette';
type Prefix={text:string;color?:string;priority:number};type Player={id:string;name:string;ready:boolean;host:boolean;score:number;avatar:string;prefix?:Prefix};
type Msg={id:string;playerId?:string;name:string;text:string;system?:boolean;at:number};
type Answer={id:string;playerId:string;text:string;votes:string[]};
type AnswerGame={mode:'answer';phase:'answering'|'voting'|'results';round:number;maxRounds:number;prompt:string;answers:Answer[]};
type Bluff={id:string;playerId?:string;text:string;votes:string[];truth:boolean};
type BluffGame={mode:'bluff';phase:'answering'|'voting'|'results';round:number;maxRounds:number;question:string;truth:string;answers:Bluff[]};
type Mission={playerId:string;targetId:string;trigger:string;done:boolean};
type TrapGame={mode:'trap';phase:'playing'|'results';round:number;maxRounds:number;endsAt:number;missions:Mission[];completed?:{hunterId:string;targetId:string;trigger:string;message:string}[]};
type WhoGuess={guesserId:string;guessedPlayerId:string};
