type WhoGame={mode:'who';phase:'answering'|'guessing'|'results';round:number;maxRounds:number;prompt:string;answers:WhoAnswer[]};
type DrawEntry={kind:'prompt'|'drawing'|'description';playerId?:string;value:string};
type DrawChain={id:string;entries:DrawEntry[]};
type DrawGame={mode:'draw';phase:'playing'|'results';round:number;maxRounds:number;step:number;maxSteps:number;submitted:string[];chains:DrawChain[]};
type MonsterPart={kind:'head'|'body'|'legs';playerId:string;value:string};
type MonsterChain={id:string;parts:MonsterPart[]};
type MonsterGame={mode:'monster';phase:'playing'|'results';round:number;maxRounds:number;step:number;submitted:string[];chains:MonsterChain[]};
type StoryEntry={playerId:string;words:string};
type StoryChain={id:string;entries:StoryEntry[]};
type StoryGame={mode:'story';phase:'playing'|'results';round:number;maxRounds:number;step:number;maxSteps:number;submitted:string[];chains:StoryChain[]};
type TankP={x:number;y:number;hp:number;score:number;angle:number;lastShot:number;respawnAt:number;bigUntil:number;smallUntil:number;radialUntil:number};
type TankBullet={id:string;ownerId:string;x:number;y:number;vx:number;vy:number;r:number;damage:number;born:number};
type TankDrop={id:string;x:number;y:number;kind:'big'|'small'|'radial'};
type TanksGame={mode:'tanks';phase:'playing'|'results';round:number;maxRounds:number;endsAt:number;tanks:Record<string,TankP>;bullets:TankBullet[];drops:TankDrop[];nextDropAt:number};
type WhaleP={x:number;alive:boolean;score:number;gap:number};
type WhaleObstacle={id:string;x:number;y:number;w:number;h:number};
type WhaleGame={mode:'whale';phase:'playing'|'results';round:number;maxRounds:number;endsAt:number;startedAt:number;players:Record<string,WhaleP>;obstacles:WhaleObstacle[];nextSpawnAt:number};
type AlibiEvidence={id:string;ownerId:string;text:string;real:boolean;guess?:boolean};
type AlibiGame={mode:'alibi';phase:'playing'|'guessing'|'results';round:number;maxRounds:number;accusedId:string;charge:string;alibi:string[];evidence:AlibiEvidence[];endsAt:number};
type Game=AnswerGame|BluffGame|TrapGame|WhoGame|DrawGame|MonsterGame|StoryGame|TanksGame|WhaleGame|AlibiGame;
type MCPlayer={x:number;y:number;hp:number;hunger:number;inv:Record<string,number>;tool:'hand'|'wood_pick'|'stone_sword'|'hoe'}; type MCMob={id:string;kind:'zombie'|'pig'|'cow';x:number;y:number;hp:number;breed?:number}; type Minecraft={seed:number;blocks:Record<string,string>;players:Record<string,MCPlayer>;mobs:MCMob[];grown:Record<string,number>};
type GtaWeapon='pistol'|'rifle'|'rocket'|'grenade'|'drone';
type GtaP={x:number;y:number;hp:number;score:number;weapon:GtaWeapon;owned:GtaWeapon[];vehicleId?:string;lastShot:number;respawnAt:number;angle:number};
type GtaVehicle={id:string;kind:'car'|'bike'|'tank';x:number;y:number;hp:number;driverId?:string;angle:number};
type GtaShot={id:string;ownerId:string;kind:GtaWeapon|'cannon';x:number;y:number;vx:number;vy:number;born:number;explodeAt?:number};
type GtaPickup={id:string;kind:GtaWeapon;x:number;y:number};
type GTA={players:Record<string,GtaP>;vehicles:GtaVehicle[];shots:GtaShot[];pickups:GtaPickup[]};
type Room={code:string;players:Player[];messages:Msg[];selectedMode:Mode;adminIds?:string[];notifications?:{id:string;text:string;kind:string;at:number}[];game?:Game;lastMode?:Exclude<Mode,'roulette'>;finalStandings?:Player[];paused?:boolean;pausedAt?:number;skipVotes?:string[];minecraft?:Minecraft;gta?:GTA;whoPromptHistory?:string[]};

const app=express();app.use(cors());app.use(express.json());
const http=createServer(app);const io=new Server(http,{cors:{origin:'*'},maxHttpBufferSize:2_000_000});const rooms=new Map<string,Room>();
app.get('/health',(_req,res)=>res.json({ok:true,rooms:rooms.size}));
function clean(v:any,max:number){return String(v??'').trim().slice(0,max)}
function makeCode(){for(let i=0;i<900;i++){const code=String(100+Math.floor(Math.random()*900));if(!rooms.has(code))return code}throw new Error('Нет свободных кодов комнат')}
function emit(r:Room){io.to(r.code).emit('room:state',r)}
function prefixFor(name:string):Prefix|undefined{const n=name.toLocaleLowerCase('ru');if(['blagin','благин'].includes(n))return {text:'БОСС',priority:100,color:'#ffcc00'};if(n==='саша'||n==='саня'||n==='александр')return {text:'СПОНСОР 12₽',priority:80,color:'#00e5ff'};if(n==='филатов')return {text:'СПОНСОР 10₽',priority:60,color:'#ff66cc'};return undefined}
function notify(r:Room,text:string,kind='info'){r.notifications??=[];r.notifications.push({id:crypto.randomUUID(),text,kind,at:Date.now()});r.notifications=r.notifications.slice(-10);io.to(r.code).emit('notification',r.notifications[r.notifications.length-1])}

function sys(r:Room,text:string){r.messages.push({id:crypto.randomUUID(),name:'Система',text,system:true,at:Date.now()});r.messages=r.messages.slice(-100)}
function resetReady(r:Room){r.players.forEach(p=>p.ready=false)}
function resetRoundControls(r:Room){r.skipVotes=[];r.paused=false;r.pausedAt=undefined}
function timedRemaining(r:Room){const g=r.game as any;return g?.endsAt?Math.max(0,g.endsAt-Date.now()):0}
function scheduleCheck(r:Room,kind:'trap'|'alibi-play'|'alibi-guess',round:number){setTimeout(()=>{const g=r.game as any;if(!g||g.round!==round)return;if(r.paused)return scheduleCheck(r,kind,round);const left=timedRemaining(r);if(left>0)return setTimeout(()=>scheduleCheck(r,kind,round),Math.min(left+20,500));if(kind==='trap'&&g.mode==='trap'&&g.phase==='playing')finishTrap(r);if(kind==='alibi-play'&&g.mode==='alibi'&&g.phase==='playing')beginAlibiGuessing(r,round);if(kind==='alibi-guess'&&g.mode==='alibi'&&g.phase==='guessing')finishAlibi(r,round)},250)}

