function generateWhoPrompt(r:Room){r.whoPromptHistory??=[];for(let tries=0;tries<80;tries++){const i=Math.floor(Math.random()*40),t=Math.floor(Math.random()*whoTemplates.length),q=whoTemplates[t](i);if(!r.whoPromptHistory.includes(q)){r.whoPromptHistory.push(q);r.whoPromptHistory=r.whoPromptHistory.slice(-80);return q}}return whoTemplates[Math.floor(Math.random()*whoTemplates.length)](Math.floor(Math.random()*40))}
