function randomOf<T>(xs:T[]){return xs[Math.floor(Math.random()*xs.length)]}
function generateDrawPrompt(){return `${randomOf(drawSubjects)} ${randomOf(drawActions)} ${randomOf(drawObjects)} ${randomOf(drawCircumstances)} ${randomOf(drawModifiers)}`}
function makeDrawPrompts(count:number){const out:string[]=[];const seen=new Set<string>();while(out.length<count){const useManual=Math.random()<0.28;const prompt=useManual?randomOf(drawPrompts):generateDrawPrompt();if(!seen.has(prompt)){seen.add(prompt);out.push(prompt)}}return out}

const alibiCases=[
 {charge:'украл все мышки из кабинета информатики',alibi:['В 19:30 ты зашёл в магазин.','Ты был там один.','Купил арбуз и воду.','Вышел в 20:05.'],real:['Чек из магазина пробит в 19:47.','Камера магазина сняла тебя без компании.','На банковской карте есть покупка воды в 19:48.'],fake:['Магазин закрылся ещё в 18:00.','Камера школы сняла тебя в кабинете в 19:40.','Продавец утверждает, что ты покупал отвёртку.']},
 {charge:'продал школьный проектор на Avito',alibi:['С 17:00 до 18:00 ты был в компьютерном клубе.','Ты пришёл туда с Димой.','Платил наличными.','Домой ушёл пешком.'],real:['Администратор клуба помнит тебя около 17:20.','Дима подтвердил, что пришёл вместе с тобой.','Камера у клуба сняла тебя в 17:54.'],fake:['На твоей карте есть оплата такси в 17:15.','Дима заявил, что весь день тебя не видел.','Покупатель проектора назвал твоё имя.']},
 {charge:'съел чужой доширак и подделал алиби',alibi:['Во время пропажи ты сидел в библиотеке.','С собой у тебя был только чай.','Ты ушёл оттуда в 14:10.','До библиотеки ты пришёл на автобусе.'],real:['Библиотекарь видел тебя за столом.','Проездной отмечен в автобусе в 12:58.','Камера выхода показывает тебя в 14:09.'],fake:['В мусорке нашли упаковку с твоими отпечатками.','Библиотека в тот день была закрыта.','Камера столовой сняла тебя с дошираком.']},
 {charge:'ночью переставил все клавиши на школьных клавиатурах',alibi:['В 23:00 ты уже был дома.','Ты играл за компьютером.','С тобой в Discord сидел друг.','Из дома после 22:30 ты не выходил.'],real:['Друг подтвердил звонок в Discord в 23:12.','Домашний роутер зафиксировал твой компьютер онлайн.','Камера подъезда не показывает твоего выхода после 22:30.'],fake:['Твой пропуск использовали в школе в 23:18.','Таксист узнал тебя по фотографии.','На одной клавиатуре нашли твою записку.']}
];
const realModes:Exclude<Mode,'roulette'>[]=['answer','bluff','trap','who','draw','monster','story','tanks','whale','alibi'];
function chooseRoulette(r:Room){const pool=realModes.filter(x=>x!==r.lastMode);return pool[Math.floor(Math.random()*pool.length)]||'answer'}
function modeName(m:Exclude<Mode,'roulette'>){return m==='answer'?'Ответь как еблан':m==='bluff'?'Хуй знает':m==='trap'?'Подстава':m==='who'?'Кто это написал?':m==='draw'?'Фоторобот':m==='monster'?'Сын пробирки':m==='story'?'Продолжи историю':m==='tanks'?'Танчики':m==='whale'?'Беги от кита':'Алиби'}
function startGame(r:Room){resetReady(r);r.finalStandings=undefined;const chosen=r.selectedMode==='roulette'?chooseRoulette(r):r.selectedMode;r.lastMode=chosen;if(r.selectedMode==='roulette')sys(r,`Рулетка выбрала режим: ${modeName(chosen)}.`);if(chosen==='answer')startAnswer(r,1);else if(chosen==='bluff')startBluff(r,1);else if(chosen==='trap')startTrap(r,1);else if(chosen==='who')startWho(r,1);else if(chosen==='draw')startDraw(r,1);else if(chosen==='monster')startMonster(r);else if(chosen==='story')startStory(r);else if(chosen==='tanks')startTanks(r);else if(chosen==='whale')startWhale(r);else startAlibi(r,1)}
function startAnswer(r:Room,round:number){resetRoundControls(r);r.game={mode:'answer',phase:'answering',round,maxRounds:3,prompt:answerPrompts[(round-1)%answerPrompts.length],answers:[]};sys(r,`Раунд ${round} начался.`);emit(r)}
function startBluff(r:Room,round:number){resetRoundControls(r);const x=bluffQuestions[(round-1)%bluffQuestions.length];r.game={mode:'bluff',phase:'answering',round,maxRounds:3,question:x.q,truth:x.a,answers:[]};sys(r,`Раунд ${round} начался.`);emit(r)}
function startWho(r:Room,round:number){resetRoundControls(r);r.game={mode:'who',phase:'answering',round,maxRounds:3,prompt:generateWhoPrompt(r),answers:[]};sys(r,`Кто это написал?: раунд ${round}.`);emit(r)}
function startDraw(r:Room,round:number){resetRoundControls(r);const prompts=makeDrawPrompts(r.players.length);const chains:DrawChain[]=r.players.map((p,i)=>({id:crypto.randomUUID(),entries:[{kind:'prompt' as const,value:prompts[i]}]}));r.game={mode:'draw',phase:'playing',round,maxRounds:2,step:0,maxSteps:Math.max(3,Math.min(5,r.players.length)),submitted:[],chains};sys(r,`Фоторобот: раунд ${round}.`);emit(r)}
function drawTask(r:Room,g:DrawGame,playerId:string){const idx=r.players.findIndex(p=>p.id===playerId);if(idx<0)return null;const chain=g.chains[(idx-g.step%r.players.length+r.players.length)%r.players.length];const last=chain.entries[chain.entries.length-1];return{chainId:chain.id,kind:g.step%2===0?'drawing':'description',source:last}}
function advanceDraw(r:Room,g:DrawGame){if(g.submitted.length<r.players.length)return;g.submitted=[];g.step++;if(g.step>=g.maxSteps){g.phase='results';emit(r);return}emit(r)}
function startMonster(r:Room){resetRoundControls(r);r.game={mode:'monster',phase:'playing',round:1,maxRounds:1,step:0,submitted:[],chains:r.players.map(()=>({id:crypto.randomUUID(),parts:[]}))};sys(r,'Сын пробирки: сначала головы, затем чужие тела, затем чужие ноги.');emit(r)}
function monsterTask(r:Room,g:MonsterGame,playerId:string){const idx=r.players.findIndex(p=>p.id===playerId);if(idx<0)return null;const chain=g.chains[(idx-g.step%r.players.length+r.players.length)%r.players.length];return chain}
function advanceMonster(r:Room,g:MonsterGame){if(g.submitted.length<r.players.length)return;g.submitted=[];g.step++;if(g.step>=3)g.phase='results';emit(r)}
function startStory(r:Room){resetRoundControls(r);r.game={mode:'story',phase:'playing',round:1,maxRounds:1,step:0,maxSteps:6,submitted:[],chains:r.players.map(()=>({id:crypto.randomUUID(),entries:[]}))};sys(r,'Продолжи историю: каждый пишет ровно два слова, потом цепочка переходит другому игроку.');emit(r)}
function storyTask(r:Room,g:StoryGame,playerId:string){const idx=r.players.findIndex(p=>p.id===playerId);if(idx<0)return null;return g.chains[(idx-g.step%r.players.length+r.players.length)%r.players.length]}
function advanceStory(r:Room,g:StoryGame){if(g.submitted.length<r.players.length)return;g.submitted=[];g.step++;if(g.step>=g.maxSteps)g.phase='results';emit(r)}
const tankWalls=[{x:250,y:150,w:130,h:28},{x:620,y:140,w:28,h:160},{x:430,y:360,w:160,h:28},{x:120,y:390,w:110,h:28},{x:760,y:400,w:110,h:28}];
function tankBlocked(x:number,y:number,radius=18){return tankWalls.some(w=>x+radius>w.x&&x-radius<w.x+w.w&&y+radius>w.y&&y-radius<w.y+w.h)}
function startTanks(r:Room){resetRoundControls(r);const tanks:Record<string,TankP>={};r.players.forEach((p,i)=>{const spots=[[90,90],[910,530],[910,90],[90,530],[500,80],[500,540]];const q=spots[i%spots.length];tanks[p.id]={x:q[0],y:q[1],hp:100,score:0,angle:0,lastShot:0,respawnAt:0,bigUntil:0,smallUntil:0,radialUntil:0}});r.game={mode:'tanks',phase:'playing',round:1,maxRounds:1,endsAt:Date.now()+90000,tanks,bullets:[],drops:[],nextDropAt:Date.now()+5000};sys(r,'Танчики: 90 секунд. WASD — движение, ПКМ — выстрел. Аирдропы дают усиление на 10 секунд.');emit(r)}
function tankBullet(g:TanksGame,ownerId:string,x:number,y:number,ang:number,radius:number,damage:number){g.bullets.push({id:crypto.randomUUID(),ownerId,x,y,vx:Math.cos(ang)*10,vy:Math.sin(ang)*10,r:radius,damage,born:Date.now()})}
function tanksTick(r:Room,g:TanksGame){if(g.phase!=='playing')return;const now=Date.now();if(now>=g.endsAt){for(const [id,t] of Object.entries(g.tanks)){const p=r.players.find(p=>p.id===id);if(p)p.score=t.score}g.phase='results';emit(r);return}if(now>=g.nextDropAt&&g.drops.length<4){g.drops.push({id:crypto.randomUUID(),x:70+Math.random()*860,y:70+Math.random()*460,kind:randomOf(['big','small','radial'] as const)});g.nextDropAt=now+7000+Math.random()*5000}for(const [id,t] of Object.entries(g.tanks)){if(t.hp<=0&&now>=t.respawnAt){const q=[[90,90],[910,530],[910,90],[90,530],[500,80],[500,540]][Math.floor(Math.random()*6)];t.x=q[0];t.y=q[1];t.hp=100}for(const d of [...g.drops])if(Math.hypot(t.x-d.x,t.y-d.y)<30){if(d.kind==='big')t.bigUntil=now+10000;if(d.kind==='small')t.smallUntil=now+10000;if(d.kind==='radial')t.radialUntil=now+10000;g.drops=g.drops.filter(x=>x.id!==d.id)}}for(const b of [...g.bullets]){b.x+=b.vx;b.y+=b.vy;if(now-b.born>4000||b.x<0||b.x>1000||b.y<0||b.y>620||tankBlocked(b.x,b.y,b.r)){g.bullets=g.bullets.filter(x=>x.id!==b.id);continue}for(const [id,t] of Object.entries(g.tanks)){if(id===b.ownerId||t.hp<=0)continue;const rr=(now<t.smallUntil?11:19)+b.r;if(Math.hypot(t.x-b.x,t.y-b.y)<rr){t.hp-=b.damage;g.bullets=g.bullets.filter(x=>x.id!==b.id);if(t.hp<=0){t.hp=0;t.respawnAt=now+3000;const killer=g.tanks[b.ownerId];if(killer)killer.score++}break}}}emit(r)}
function startWhale(r:Room){resetRoundControls(r);const players:Record<string,WhaleP>={};r.players.forEach((p,i)=>players[p.id]={x:.25+(i%4)*.16,alive:true,score:0,gap:.44});r.game={mode:'whale',phase:'playing',round:1,maxRounds:1,endsAt:Date.now()+90000,startedAt:Date.now(),players,obstacles:[],nextSpawnAt:Date.now()+850};sys(r,'Погоня от кита: только влево/вправо. Препятствия несутся от горизонта; если застрял — выбирайся в сторону, пока кит не догнал.');emit(r)}
function whaleTick(r:Room,g:WhaleGame){if(g.phase!=='playing')return;const now=Date.now(),elapsed=(now-g.startedAt)/1000,diff=1+elapsed/24,speed=.0105*diff;if(now>=g.nextSpawnAt){const w=.055+Math.random()*.095;g.obstacles.push({id:crypto.randomUUID(),x:.08+Math.random()*(.84-w),y:.03,w,h:.045+Math.random()*.035});g.nextSpawnAt=now+Math.max(220,820/diff)}for(const o of g.obstacles)o.y+=speed;g.obstacles=g.obstacles.filter(o=>o.y<1.08);for(const p of Object.values(g.players)){if(!p.alive)continue;p.score=Math.floor(elapsed*12);const hit=g.obstacles.some(o=>o.y<.91&&o.y+o.h>.77&&p.x+.026>o.x&&p.x-.026<o.x+o.w);p.gap-=.00034*diff;if(hit)p.gap-=.0052*diff;else p.gap=Math.min(.46,p.gap+.00062);if(p.gap<=.035)p.alive=false}if(now>=g.endsAt||Object.values(g.players).every(p=>!p.alive)){for(const [id,q] of Object.entries(g.players)){const p=r.players.find(p=>p.id===id);if(p)p.score=q.score}g.phase='results'}emit(r)}

function startTrap(r:Room,round:number){resetRoundControls(r);const shuffled=[...trapWords].sort(()=>Math.random()-.5);const missions=r.players.map((p,i)=>{const targets=r.players.filter(x=>x.id!==p.id);const target=targets[Math.floor(Math.random()*targets.length)];return{playerId:p.id,targetId:target.id,trigger:shuffled[i%shuffled.length],done:false}});r.game={mode:'trap',phase:'playing',round,maxRounds:3,endsAt:Date.now()+60000,missions,completed:[]};sys(r,`Подстава: раунд ${round}. У вас 60 секунд.`);emit(r);scheduleCheck(r,'trap',round)}
function finishTrap(r:Room){const g=r.game;if(!g||g.mode!=='trap'||g.phase!=='playing')return;g.phase='results';emit(r)}

function startAlibi(r:Room,round:number){resetRoundControls(r);const accused=r.players[(round-1)%r.players.length];const c=alibiCases[(round-1)%alibiCases.length];const investigators=r.players.filter(p=>p.id!==accused.id);const pool=[...c.real.map(text=>({text,real:true})),...c.fake.map(text=>({text,real:false}))].sort(()=>Math.random()-.5);const evidence=investigators.map((p,i)=>({id:crypto.randomUUID(),ownerId:p.id,...pool[i%pool.length]}));r.game={mode:'alibi',phase:'playing',round,maxRounds:Math.min(3,r.players.length),accusedId:accused.id,charge:c.charge,alibi:c.alibi,evidence,endsAt:Date.now()+45000};sys(r,`Алиби: ${accused.name} под подозрением. Следователи получили улики.`);emit(r);scheduleCheck(r,'alibi-play',round)}
function beginAlibiGuessing(r:Room,round:number){const g=r.game;if(!g||g.mode!=='alibi'||g.round!==round||g.phase!=='playing')return;g.phase='guessing';r.skipVotes=[];g.endsAt=Date.now()+30000;sys(r,'Допрос окончен. Подозреваемый должен определить, какие улики настоящие.');emit(r);scheduleCheck(r,'alibi-guess',round)}
function finishAlibi(r:Room,round:number){const g=r.game;if(!g||g.mode!=='alibi'||g.round!==round||g.phase==='results')return;const accused=r.players.find(p=>p.id===g.accusedId);for(const e of g.evidence){const owner=r.players.find(p=>p.id===e.ownerId);if(e.guess===e.real){if(accused)accused.score+=300}else if(e.guess!==undefined&&owner)owner.score+=400}g.phase='results';emit(r)}

function beginVoting(r:Room){const g=r.game;if(!g||g.phase!=='answering'||g.mode==='who')return;if(g.mode==='bluff')g.answers.push({id:crypto.randomUUID(),text:g.truth,votes:[],truth:true});g.phase='voting';emit(r)}
function finishVoting(r:Room){const g=r.game;if(!g||(g.mode!=='answer'&&g.mode!=='bluff')||g.phase!=='voting')return;if(g.mode==='answer'){for(const a of g.answers){const owner=r.players.find(p=>p.id===a.playerId);if(owner)owner.score+=a.votes.length*100}}else{for(const a of g.answers){if(a.truth){for(const voter of a.votes){const p=r.players.find(x=>x.id===voter);if(p)p.score+=1000}}else if(a.playerId){const owner=r.players.find(p=>p.id===a.playerId);if(owner)owner.score+=a.votes.length*500}}}g.phase='results';emit(r)}
function totalVotes(g:AnswerGame|BluffGame){return g.answers.reduce((n,a)=>n+a.votes.length,0)}
function finishGame(r:Room){r.finalStandings=[...r.players].sort((a,b)=>b.score-a.score).map(p=>({...p}));r.game=undefined;resetReady(r);sys(r,'Игра закончена.');emit(r)}

function normalizeName(raw:any){const n=clean(raw,20)||'Игрок';return n.toLocaleLowerCase('ru')==='ефим'?'петух':n}
const avatars=['😎','🤡','🐸','🐱','🐶','🦆','🐧','🦝','🗿','👽','🤖','💀','🧙','🥸','🐔'];
function mcNoise(seed:number,x:number,y:number){const n=Math.sin(x*12.9898+y*78.233+seed*.0001)*43758.5453;return n-Math.floor(n)}
function mcBase(mc:Minecraft,x:number,y:number){const h=Math.sin((x+mc.seed%97)*.075)+Math.cos((y-mc.seed%71)*.068)+Math.sin((x+y)*.031);if(h>1.28)return 'water';if(h>.68)return 'stone';if(h<-.95)return 'sand';const tree=mcNoise(mc.seed,x,y);return tree>.965?'wood':'grass'}
function mcTile(mc:Minecraft,x:number,y:number){const k=`${x},${y}`;return mc.blocks[k]??mcBase(mc,x,y)}
function mcWalkable(b:string){return !['water','stone','wood','wall','door_closed'].includes(b)}
function mcSpawn(mc:Minecraft,nearX=0,nearY=0){for(let r=0;r<80;r++)for(let y=nearY-r;y<=nearY+r;y++)for(let x=nearX-r;x<=nearX+r;x++){const b=mcTile(mc,x,y);if(['grass','sand','farmland','carrot'].includes(b))return{x,y}}return{x:0,y:0}}
function makeMinecraft(r:Room){const seed=Math.floor(Math.random()*1e9),blocks:Record<string,string>={},grown:Record<string,number>={};const players:Record<string,MCPlayer>={};const mc:Minecraft={seed,blocks,players,mobs:[],grown};const sp=mcSpawn(mc);r.players.forEach((p,i)=>{const q=mcSpawn(mc,sp.x+(i%3)*2,sp.y+Math.floor(i/3)*2);players[p.id]={x:q.x,y:q.y,hp:20,hunger:20,inv:{wood:0,stone:0,carrot:2,wall:0,door:0},tool:'hand'}});for(let i=0;i<24;i++){const q=mcSpawn(mc,sp.x-18+Math.floor(Math.random()*37),sp.y-14+Math.floor(Math.random()*29));mc.mobs.push({id:crypto.randomUUID(),kind:i<8?'zombie':i<16?'pig':'cow',x:q.x,y:q.y,hp:i<8?8:10})}r.minecraft=mc;r.gta=undefined;r.game=undefined;sys(r,'Секретный режим активирован: Minecraft.');emit(r)}

const gtaBuildings=[{x:260,y:120,w:250,h:180},{x:760,y:80,w:260,h:220},{x:1240,y:120,w:300,h:170},{x:160,y:600,w:280,h:260},{x:700,y:520,w:310,h:220},{x:1250,y:590,w:350,h:260}];
function gtaBlocked(x:number,y:number,radius=18){return gtaBuildings.some(b=>x+radius>b.x&&x-radius<b.x+b.w&&y+radius>b.y&&y-radius<b.y+b.h)}
function makeGta(r:Room){const players:Record<string,GtaP>={};r.players.forEach((p,i)=>{const spawn=[[90,90],[1710,1050],[90,1050],[1710,90],[900,1020],[900,90]][i%6];players[p.id]={x:spawn[0],y:spawn[1],hp:100,score:0,weapon:'pistol',owned:['pistol'],lastShot:0,respawnAt:0,angle:0}});const vehicles:GtaVehicle[]=[['car',560,180],['bike',1080,180],['tank',900,390],['car',520,930],['bike',1110,930],['tank',1650,520]].map((v:any)=>({id:crypto.randomUUID(),kind:v[0],x:v[1],y:v[2],hp:v[0]==='tank'?300:150,angle:0}));const kinds:GtaWeapon[]=['rifle','rocket','grenade','drone'];const pickups:GtaPickup[]=[[590,430],[1110,420],[550,520],[1110,520],[900,880],[1500,420],[90,520],[1700,930]].map((q:any,i)=>({id:crypto.randomUUID(),kind:kinds[i%kinds.length],x:q[0],y:q[1]}));r.gta={players,vehicles,shots:[],pickups};r.minecraft=undefined;r.game=undefined;sys(r,'GTA-режим запущен. WASD — движение, ЛКМ/кнопка — огонь, E — сесть/выйти, Q — сменить оружие.');emit(r)}
function gtaExplode(g:GTA,ownerId:string,x:number,y:number,radius:number,damage:number,safeOwner=false){for(const [id,p] of Object.entries(g.players)){if(p.hp<=0||safeOwner&&id===ownerId)continue;const d=Math.hypot(p.x-x,p.y-y);if(d<radius){p.hp-=Math.max(5,damage*(1-d/radius));if(p.hp<=0){p.hp=0;p.respawnAt=Date.now()+3000;const k=g.players[ownerId];if(k&&id!==ownerId)k.score++}}}for(const v of g.vehicles){const d=Math.hypot(v.x-x,v.y-y);if(d<radius)v.hp-=Math.max(8,damage*(1-d/radius))}}
function gtaTick(r:Room,g:GTA){const now=Date.now();for(const [id,p] of Object.entries(g.players)){if(p.hp<=0&&now>=p.respawnAt){const spawn=[[90,90],[1710,1050],[90,1050],[1710,90],[900,1020],[900,90]][Math.floor(Math.random()*6)];p.x=spawn[0];p.y=spawn[1];p.hp=100;p.vehicleId=undefined}for(const pick of g.pickups)if(Math.hypot(p.x-pick.x,p.y-pick.y)<35&&!p.owned.includes(pick.kind)){p.owned.push(pick.kind);p.weapon=pick.kind}}
for(const sh of [...g.shots]){sh.x+=sh.vx;sh.y+=sh.vy;const age=now-sh.born;const timed=sh.explodeAt&&now>=sh.explodeAt;const wall=sh.x<0||sh.x>1800||sh.y<0||sh.y>1200||gtaBlocked(sh.x,sh.y,5);let hit=false;for(const [id,p] of Object.entries(g.players)){if(id===sh.ownerId||p.hp<=0)continue;if(Math.hypot(p.x-sh.x,p.y-sh.y)<18){if(['rocket','grenade','drone','cannon'].includes(sh.kind))gtaExplode(g,sh.ownerId,sh.x,sh.y,sh.kind==='grenade'?115:sh.kind==='cannon'?150:135,sh.kind==='cannon'?90:70,sh.kind==='grenade');else{p.hp-=sh.kind==='rifle'?18:28;if(p.hp<=0){p.hp=0;p.respawnAt=now+3000;const k=g.players[sh.ownerId];if(k)k.score++}}hit=true;break}}if(timed||wall){if(['rocket','grenade','drone','cannon'].includes(sh.kind))gtaExplode(g,sh.ownerId,sh.x,sh.y,sh.kind==='grenade'?115:sh.kind==='cannon'?150:135,sh.kind==='cannon'?90:70,sh.kind==='grenade');hit=true}if(hit||age>7000)g.shots=g.shots.filter(x=>x.id!==sh.id)}
for(const v of g.vehicles)if(v.hp<=0){if(v.driverId){const p=g.players[v.driverId];if(p)p.vehicleId=undefined;v.driverId=undefined}v.hp=v.kind==='tank'?300:150;v.x=100+Math.random()*1600;v.y=100+Math.random()*1000}emit(r)}

function mcTick(r:Room){const mc=r.minecraft;if(!mc)return;for(const p of Object.values(mc.players)){p.hunger=Math.max(0,p.hunger-.02);if(p.hunger<=0)p.hp=Math.max(0,p.hp-.04)}for(const [k,t] of Object.entries(mc.grown)){if(Date.now()-t>25000){mc.blocks[k]='carrot';delete mc.grown[k]}}for(const m of mc.mobs){if(m.kind==='zombie'){const targets=Object.values(mc.players).filter(p=>p.hp>0);if(!targets.length)continue;const t=targets.sort((a,b)=>Math.hypot(a.x-m.x,a.y-m.y)-Math.hypot(b.x-m.x,b.y-m.y))[0];if(Math.hypot(t.x-m.x,t.y-m.y)<7){const nx=m.x+Math.sign(t.x-m.x)*.12,ny=m.y+Math.sign(t.y-m.y)*.12;if(mcWalkable(mcTile(mc,Math.round(nx),Math.round(ny)))){m.x=nx;m.y=ny}if(Math.hypot(t.x-m.x,t.y-m.y)<1)t.hp=Math.max(0,t.hp-.12)}}else if(Math.random()<.18){const nx=m.x+(Math.random()-.5)*.5,ny=m.y+(Math.random()-.5)*.5;if(mcWalkable(mcTile(mc,Math.round(nx),Math.round(ny)))){m.x=nx;m.y=ny}}}emit(r)}
setInterval(()=>{for(const r of rooms.values())if(r.minecraft)mcTick(r)},1000);
setInterval(()=>{for(const r of rooms.values()){const g=r.game;if(g?.mode==='tanks')tanksTick(r,g);else if(g?.mode==='whale')whaleTick(r,g);if(r.gta)gtaTick(r,r.gta)}},80);
